mapper.update:
UPDATE tb_question
SET question_views = IFNULL(question_views, 0) + 1
WHERE question_id = #{questionId}

mapper.select:
SELECT q.question_id, q.question_title, c.category_name, u.user_nickname, q.question_views, q.created_at, q.is_qualified, q.is_deleted FROM tb_question q JOIN tb_category c ON q.category_id = c.category_id JOIN tb_user u ON q.user_id = u.user_id WHERE 1=1
AND ( q.question_title LIKE CONCAT('%', #{keyword}, '%') OR q.question_question LIKE CONCAT('%', #{keyword}, '%') )
AND q.is_qualified = #{verified.name()}
AND q.is_deleted = #{deleted.name()}
ORDER BY q.created_at DESC
LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*)
FROM tb_question q
WHERE 1=1

    AND (
    q.question_title    LIKE CONCAT('%', #{keyword}, '%')
    OR q.question_question LIKE CONCAT('%', #{keyword}, '%')
    )


    AND q.is_qualified = #{verified.name()}


    AND q.is_deleted = #{deleted.name()}
